           {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
         </div>

         <div className="form-field">
           <label htmlFor="phone">Phone number (optional)</label>
           <p id="phone-help" className="help-text">Expected format: 123-456-7890</p>
           <input
             ref={phoneInputRef}
             id="phone"
             name="phone"
             type="tel"
             autoComplete="tel"
             value={formData.phone}
             onChange={handleChange}
             aria-invalid={!!errors.phone}
             aria-describedby={`phone-help ${errors.phone ? 'phone-error' : ''}`.trim()}
           />
           {errors.phone && <p id="phone-error" className="error-text">{errors.phone}</p>}
         </div>

         <button type="submit">Send message</button>
       </form>
     </div>
   );
 }

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ContactForm />);
     </script>
