    setFormData(prev => ({ ...prev, [name]: value }));

    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const newErrors = { name: '', email: '', phone: '' };
    let hasError = false;
    let firstInvalidFieldRef = null;

    if (!formData.name.trim()) {
      newErrors.name = 'Error: Full name is required.';
      hasError = true;
      if (!firstInvalidFieldRef) firstInvalidFieldRef = nameInputRef;
