    if (!formData.email.trim()) {
      newErrors.email = 'Error: Email address is required.';
      hasError = true;
      if (!firstInvalidFieldRef) firstInvalidFieldRef = emailInputRef;
    } else if (!validateEmail(formData.email)) {
      newErrors.email = 'Error: Enter a valid email address like name@example.com.';
      hasError = true;
      if (!firstInvalidFieldRef) firstInvalidFieldRef = emailInputRef;
    }

    if (formData.phone && !validatePhone(formData.phone)) {
      newErrors.phone = 'Error: Enter a valid phone number like 123-456-7890.';
      hasError = true;
      if (!firstInvalidFieldRef) firstInvalidFieldRef = phoneInputRef;
    }

    setErrors(newErrors);

    if (hasError) {
      if (firstInvalidFieldRef && firstInvalidFieldRef.current) {
        firstInvalidFieldRef.current.focus();
      }
    } else {
      setIsSubmitted(true);
    }
  };

  if (isSubmitted) {
    return (
      <div className="contact-container" role="status" aria-live="polite">
